/* ==========================================================
   ESTILOS PREMIUM RIDE FACTURA ELECTRÓNICA
   Frappe Framework - Ecuador
   ========================================================== */


/* ============================
   CONTENEDOR PRINCIPAL HEADER
   ============================ */

.header-wrap {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  align-items: flex-start;
  margin-bottom: 18px;
}


/* ============================
   COLUMNA IZQUIERDA EMPRESA
   ============================ */

.col-izq {
  width: 48%;
  float: left;
  text-align: left;
  padding: 8px;
}


/* Logo */

.logo-container {
  text-align: left;
  margin-bottom: 12px;
}


.company-logo {
  max-height: 95px;
  max-width: 220px;
  height: auto;
  width: auto;
  object-fit: contain;
}


/* Nombre empresa */

.company-name {
  font-size: 16px;
  font-weight: 700;
  color: #1f2937;
  letter-spacing: 0.3px;
  margin-bottom: 8px;
}


/* Datos empresa */

.company-data {

  font-size: 10.5px;
  color: #374151;

  line-height: 1.5;

}


/* ============================
   COLUMNA DERECHA SRI
   ============================ */

.col-der {

  width: 45%;

  float: right;

  border: 1.5px solid #111827;

  border-radius: 8px;

  padding: 14px;

  font-size: 10px;

  background: linear-gradient(
      180deg,
      #f9fafb 0%,
      #ffffff 100%
  );

  text-align: center;

  box-shadow: 0px 2px 5px rgba(0,0,0,0.08);

}


/* ============================
   TITULO FACTURA
   ============================ */

.factura-title {

  font-size: 18px;

  font-weight: 800;

  color:#111827;

  letter-spacing: 1px;

  margin: 3px 0 8px;

}


/* ============================
   RUC
   ============================ */

.ruc-box {

  background:#111827;

  color:white;

  padding:6px;

  border-radius:5px;

  font-size:12px;

  font-weight:bold;

  margin-bottom:8px;

}


/* ============================
   NUMERO FACTURA
   ============================ */

.factura-number {

  font-size:12px;

  font-weight:bold;

  color:#2563eb;

  margin:8px 0;

}


/* ============================
   CLAVE ACCESO
   ============================ */

.clave-acceso {

  font-family:'Code128';

  font-size:32px;

  text-align:center;

  white-space:nowrap;

  overflow:hidden;

  line-height:1;

  margin-top:12px;

  color:#000;

}


/* Texto debajo del código */

.clave-acceso-texto {

  font-size:9px;

  color:#4b5563;

  margin-top:5px;

  word-break:break-all;

}



/* ============================
   INFORMACIÓN ADICIONAL
   ============================ */

.info-title {

  background:#2563eb;

  color:white;

  font-size:11px;

  font-weight:bold;

  padding:6px;

  border-radius:4px;

}


.info-table {

  width:100%;

  border-collapse:collapse;

  font-size:10px;

}


.info-table td {

  border:1px solid #d1d5db;

  padding:6px;

}


.info-label {

  font-weight:bold;

  color:#374151;

  width:35%;

}


/* ============================
   TABLAS GENERALES
   ============================ */

.table-modern {

  width:100%;

  border-collapse:collapse;

  font-size:10px;

}


.table-modern th {

  background:#1f2937;

  color:white;

  padding:7px;

  font-weight:bold;

}


.table-modern td {

  border:1px solid #d1d5db;

  padding:6px;

}


.table-modern tr:nth-child(even){

  background:#f9fafb;

}



/* ============================
   TOTALES
   ============================ */

.total-box {

  border:1px solid #111827;

  border-radius:6px;

  padding:10px;

  background:#f9fafb;

}


.total-final {

  background:#111827;

  color:white;

  font-size:13px;

  font-weight:bold;

  padding:8px;

  border-radius:5px;

}



/* ============================
   TEXTOS
   ============================ */


.text-small {

  font-size:10px;

}


.text-center {

  text-align:center;

}


.text-right {

  text-align:right;

}


/* ============================
   PIE DE FACTURA
   ============================ */


.footer-rides {

  margin-top:20px;

  padding-top:10px;

  border-top:1px solid #d1d5db;

  font-size:9px;

  color:#6b7280;

  text-align:center;

}

html:
{# ==== Company & Customer ==== #}
{% set company = frappe.get_doc('Company', doc.company_id) %}
{% set customer = frappe.get_doc('Cliente', doc.customer) if doc.customer else None %}
{% set comp = doc.get_context() %}
<style>
  @page { size: A4; margin: 1.5cm; }
  @font-face {
    font-family: 'Code128';
    src: url('{{ frappe.utils.get_url() }}/assets/restaurante_app/fonts/code128.ttf') format('truetype');
  }
  .t { border: 1px solid #ccc; padding: 5px; }
</style>

{# =======================
   ACUMULADORES DE IVA
   ======================= #}
{% set ns = namespace(
  base0=0.0, base5=0.0, base12=0.0, base13=0.0, base14=0.0, base15=0.0,
  iva0=0.0,  iva5=0.0,  iva12=0.0,  iva13=0.0,  iva14=0.0,  iva15=0.0,
  subtotal=0.0, ivatotal=0.0
) %}

{# ==== Helpers visuales ==== #}
{% set access_key   = (doc.access_key or doc.clave_acceso or '') %}
{% set estab        = (doc.estab or company.establishmentcode or '001') %}
{% set ptoemi       = (doc.ptoemi or company.emissionpoint or '001') %}
{% set secuencial   = (doc.secuencial or '000000001') %}
{% set fecha_emis   = doc.posting_date %}
{% set fecha_aut    = doc.authorization_datetime or '' %}
{% set amb_raw      = (doc.environment or '') %}
{% set ambiente     =
      'PRODUCCIÓN' if amb_raw in ['2','PRODUCCION','Producción','PRODUCCIÓN'] else
      'PRUEBAS'    if amb_raw in ['1','PRUEBAS','Pruebas'] else
      (amb_raw or 'DESCONOCIDO') %}

<!-- === ENCABEZADO === -->
<div class="header-wrap">
  <!-- Columna Empresa -->
  <div class="col-izq">
    <div class="logo-container">
      <img src="{{ company.logo or '/files/sin_logo.png' }}" class="company-logo">
    </div>

    <div class="company-name">
      {{ company.businessname }}
    </div>

    <div class="company-data">
      {{ company.address or '' }}<br>
      Tel: {{ company.phone or '' }}<br>
      Email: {{ company.email or '' }}<br>
      Contribuyente Especial Nro: {{ company.contribuyente_especial or 'N/A' }}<br>
      Obligado a llevar contabilidad: {{ 'SI' if company.obligado_a_llevar_contabilidad == 1 else 'NO' }}
    </div>
  </div>

  <!-- Columna SRI / Factura -->
  <div class="col-der">
    <div><strong>R.U.C.:</strong> {{ company.ruc }}</div>
    <div class="factura-title">FACTURA</div>
    <div><strong>No.:</strong> {{ estab }}-{{ ptoemi }}-{{ secuencial }}</div>

    <div style="margin-top:6px;"><strong>No. de Autorización:</strong></div>
    <div>{{ access_key }}</div>

    <div style="margin-top:6px;"><strong>Fecha y hora de Autorización:</strong></div>
    <div>{{ fecha_aut }}</div>

    <p style="margin:6px 0 0;"><strong>Ambiente:</strong> {{ ambiente }}</p>
    <div><strong>Emisión:</strong> NORMAL</div>

    <div style="margin-top:8px;"><strong>CLAVE DE ACCESO</strong></div>
    <div class="clave-acceso">{{ access_key }}</div>
    <div class="clave-acceso-texto">{{ access_key }}</div>
  </div>
</div>


<!-- Cliente -->
<table style="width:100%; border-collapse:collapse; font-size:10px; margin-top:10px; page-break-inside:avoid;">
  <tr>
    <td class="t"><strong>Razón Social / Nombres:</strong> {{ doc.customer_name or (customer.nombre if customer else '') }}</td>
    <td class="t"><strong>Fecha Emisión:</strong> {{ fecha_emis }}</td>
  </tr>
  <tr>
    <td class="t"><strong>Identificación:</strong> {{ doc.customer_tax_id or (customer.num_identificacion if customer else '') }}</td>
    <td class="t"><strong>Dirección:</strong> {{ (customer.direccion if customer else '') or '' }}</td>
  </tr>
  <tr>
    <td class="t"><strong>Email:</strong> {{ doc.customer_email or (customer.correo if customer else '') }}</td>
    <td class="t"><strong>Teléfono:</strong> {{ (customer.telefono if customer else '') or '' }}</td>
  </tr>
</table>

<!-- Detalle -->
<table style="width:100%; border-collapse:collapse; font-size:10px; margin-top:10px; page-break-inside:avoid;">
  <thead>
    <tr style="background-color:#eaeaea; font-weight:bold;">
      <th class="t">Código</th>
      <th class="t">Cantidad</th>
      <th class="t">Descripción</th>
      <th class="t">Precio Unitario</th>
      <th class="t">Descuento</th>
      <th class="t">Subtotal</th>
    </tr>
  </thead>
  <tbody>
    {% for row in doc.items %}
      {# === Cálculos por línea ===
         Preferimos tax_rate numérico; si no existe, intentamos items.tax -> taxes.value #}
      {% set pct = (row.tax_rate if row.tax_rate is not none else (frappe.db.get_value('taxes', row.tax, 'value') if row.tax else 0)) | float %}
      {% set qty = (row.qty or 0) | float %}
      {% set rate = (row.rate or 0) | float %}
      {% set disc = (row.discount_pct or 0) | float %}
      {% if disc < 0 %}{% set disc = 0 %}{% endif %}
      {% if disc > 100 %}{% set disc = 100 %}{% endif %}
      {% set base = (qty * rate * (1 - (disc/100.0))) | float %}
      {% set iva_line = (base * (pct/100.0)) | float %}

      {# Acumular #}
      {% set ns.subtotal = ns.subtotal + base %}
      {% set ns.ivatotal = ns.ivatotal + iva_line %}
      {% if pct|int == 0 %}
        {% set ns.base0 = ns.base0 + base %}{% set ns.iva0 = ns.iva0 + iva_line %}
      {% elif pct|int == 5 %}
        {% set ns.base5 = ns.base5 + base %}{% set ns.iva5 = ns.iva5 + iva_line %}
      {% elif pct|int == 12 %}
        {% set ns.base12 = ns.base12 + base %}{% set ns.iva12 = ns.iva12 + iva_line %}
      {% elif pct|int == 13 %}
        {% set ns.base13 = ns.base13 + base %}{% set ns.iva13 = ns.iva13 + iva_line %}
      {% elif pct|int == 14 %}
        {% set ns.base14 = ns.base14 + base %}{% set ns.iva14 = ns.iva14 + iva_line %}
      {% elif pct|int == 15 %}
        {% set ns.base15 = ns.base15 + base %}{% set ns.iva15 = ns.iva15 + iva_line %}
      {% endif %}

      {% set desc_txt = row.item_name or row.description or row.item_code %}
      <tr>
        <td class="t">{{ row.item_code }}</td>
        <td class="t" style="text-align:right;">{{ qty }}</td>
        <td class="t">{{ desc_txt }}</td>
        <td class="t" style="text-align:right;">{{ "%.2f"|format(rate) }}</td>
        <td class="t" style="text-align:right;">{{ "%.2f"|format(((qty * rate) - base) if disc>0 else 0.0) }}</td>
        <td class="t" style="text-align:right;">{{ "%.2f"|format(base) }}</td>
      </tr>
    {% endfor %}
  </tbody>
</table>

<!-- Pagos y Totales -->
<div style="margin-top:15px; overflow:hidden;">
  <!-- Pagos -->
  <div style="width:48%; float:left;">
      {% if doc.additional_fields and doc.additional_fields|length > 0 %}
<table style="width:100%; border-collapse:collapse; font-size:10px; margin-bottom:10px;">
  <tr style="background:#efefef;">
    <th class="t" colspan="2">Información Adicional</th>
  </tr>

  {% for af in doc.additional_fields %}
    <tr>
      <td class="t" style="width:30%;">
        <strong>{{ af.field_name }}</strong>
      </td>
      <td class="t">
        {{ af.field_value }}
      </td>
    </tr>
  {% endfor %}

</table>
{% endif %}

    <table style="width:100%; border-collapse:collapse; font-size:10px;">
      <thead>
        <tr style="background-color:#eaeaea; font-weight:bold;">
          <th class="t">Forma de Pago</th>
          <th class="t">Valor</th>
        </tr>
      </thead>
      <tbody>
        {% if doc.payments and doc.payments|length > 0 %}
          {% for p in doc.payments %}
            <tr>
              <td class="t">{{ p.forma_pago or p.method or '—' }}</td>
              <td class="t" style="text-align:right;">{{ "%.2f"|format(p.monto or doc.grand_total or (ns.subtotal + ns.ivatotal)) }}</td>
            </tr>
          {% endfor %}
        {% else %}
          <tr>
            <td class="t">Pago</td>
            <td class="t" style="text-align:right;">{{ "%.2f"|format(doc.grand_total if doc.grand_total is not none else (ns.subtotal + ns.ivatotal)) }}</td>
          </tr>
        {% endif %}
      </tbody>
    </table>
  </div>

  <!-- Totales -->
  <div style="width:48%; float:right;">
    <table style="width:100%; border-collapse:collapse; font-size:10px;">

      {# Subtotales por tasa (solo si hay base) #}
      {% if ns.base15 > 0 %}<tr><td class="t">Subtotal 15%</td><td class="t" style="text-align:right;">{{ "%.2f"|format(ns.base15) }}</td></tr>{% endif %}
      {% if ns.base14 > 0 %}<tr><td class="t">Subtotal 14%</td><td class="t" style="text-align:right;">{{ "%.2f"|format(ns.base14) }}</td></tr>{% endif %}
      {% if ns.base13 > 0 %}<tr><td class="t">Subtotal 13%</td><td class="t" style="text-align:right;">{{ "%.2f"|format(ns.base13) }}</td></tr>{% endif %}
      {% if ns.base12 > 0 %}<tr><td class="t">Subtotal 12%</td><td class="t" style="text-align:right;">{{ "%.2f"|format(ns.base12) }}</td></tr>{% endif %}
      {% if ns.base5  > 0 %}<tr><td class="t">Subtotal 5%</td><td class="t" style="text-align:right;">{{ "%.2f"|format(ns.base5) }}</td></tr>{% endif %}
      {% if ns.base0  > 0 %}<tr><td class="t">Subtotal 0%</td><td class="t" style="text-align:right;">{{ "%.2f"|format(ns.base0) }}</td></tr>{% endif %}

      <tr>
        <td class="t">Subtotal (sin impuestos)</td>
        <td class="t" style="text-align:right;">
          {{ "%.2f"|format(doc.total_without_tax if doc.total_without_tax is not none else ns.subtotal) }}
        </td>
      </tr>

      <tr><td class="t">Descuento</td><td class="t" style="text-align:right;">0.00</td></tr>

      {# IVA por tasa (omite 0%) #}
      {% if ns.iva15 > 0 %}<tr><td class="t">IVA 15%</td><td class="t" style="text-align:right;">{{ "%.2f"|format(ns.iva15) }}</td></tr>{% endif %}
      {% if ns.iva14 > 0 %}<tr><td class="t">IVA 14%</td><td class="t" style="text-align:right;">{{ "%.2f"|format(ns.iva14) }}</td></tr>{% endif %}
      {% if ns.iva13 > 0 %}<tr><td class="t">IVA 13%</td><td class="t" style="text-align:right;">{{ "%.2f"|format(ns.iva13) }}</td></tr>{% endif %}
      {% if ns.iva12 > 0 %}<tr><td class="t">IVA 12%</td><td class="t" style="text-align:right;">{{ "%.2f"|format(ns.iva12) }}</td></tr>{% endif %}
      {% if ns.iva5  > 0 %}<tr><td class="t">IVA 5%</td><td class="t" style="text-align:right;">{{ "%.2f"|format(ns.iva5) }}</td></tr>{% endif %}

      <tr>
        <td class="t"><strong>Valor Total</strong></td>
        <td class="t" style="text-align:right;">
          <strong>{{ "%.2f"|format(doc.grand_total if doc.grand_total is not none else (ns.subtotal + ns.ivatotal)) }}</strong>
        </td>
      </tr>
    </table>
  </div>
</div>
